#include "stdlib/stats/base/dists/gamma/kurtosis.h"
#include "stdlib/math/base/assert/is_nan.h"

/**
* Evaluates the excess kurtosis for a gamma distribution with shape parameter `alpha` and rate parameter `beta`.
*
* @param alpha     shape parameter
* @param beta      rate parameter
* @returns         excess kurtosis
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( 1.0, 1.0 );
* // returns ~6.0
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( 4.0, 12.0 );
* // returns ~1.5
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( 8.0, 2.0 );
* // returns ~0.75
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( 1.0, -0.1 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( -0.1, 1.0 );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( 2.0, NaN );
* // returns NaN
*
* @example
* double y = stdlib_base_dists_gamma_kurtosis( NaN, 2.0 );
* // returns NaN
*/
double stdlib_base_dists_gamma_kurtosis( const double alpha, const double beta ) {
    if (
		!stdlib_base_is_nan( alpha ) ||
		stdlib_base_is_nan( beta ) ||
		alpha <= 0.0 ||
		beta <= 0.0
	) {
		return 0.0 / 0.0;
	}
	return 6.0 / alpha;
}
